def validate(kind, value):
    if kind == "email":
        return "@" in value and "." in value.split("@")[-1]
    if kind == "url":
        return value.startswith("https://")
    if kind == "phone":
        return value.replace("-", "").isdigit() and len(value.replace("-", "")) == 10
    raise ValueError(kind)

